// documentation for more info.
func (u *GroupUpstreamUpsertBulk) Update(set func(*GroupUpstreamUpsert)) *GroupUpstreamUpsertBulk {
	u.create.conflict = append(u.create.conflict, sql.ResolveWith(func(update *sql.UpdateSet) {
		set(&GroupUpstreamUpsert{UpdateSet: update})
	}))
	return u
}

